import React from "react";
import { Edit, Trash2 } from "lucide-react";

function JobTable({ jobs, onEdit, onDelete }) {
  // Format date helper
  const formatDate = (dateString) => {
    if (!dateString) return "N/A";

    const date = new Date(dateString);
    const now = new Date();
    const diffTime = Math.abs(now - date);
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) return "Today";
    if (diffDays === 1) return "1 day ago";
    if (diffDays < 7) return `${diffDays} days ago`;
    if (diffDays < 30) {
      const weeks = Math.floor(diffDays / 7);
      return weeks === 1 ? "1 week ago" : `${weeks} weeks ago`;
    }
    if (diffDays < 365) {
      const months = Math.floor(diffDays / 30);
      return months === 1 ? "1 month ago" : `${months} months ago`;
    }
    const years = Math.floor(diffDays / 365);
    return years === 1 ? "1 year ago" : `${years} years ago`;
  };

  const styles = {
    container: {
      backgroundColor: "#fff",
      borderRadius: "12px",
      boxShadow: "0 2px 12px rgba(0,0,0,0.05)",
      overflow: "hidden",
    },
    table: {
      width: "100%",
      borderCollapse: "collapse",
    },
    th: {
      padding: "14px 16px",
      textAlign: "left",
      fontSize: "13px",
      fontWeight: "600",
      color: "#64748b",
      textTransform: "uppercase",
      letterSpacing: "0.5px",
      borderBottom: "2px solid #e2e8f0",
      backgroundColor: "#f9fafb",
    },
    td: {
      padding: "16px",
      fontSize: "14px",
      color: "#1e293b",
      borderBottom: "1px solid #e2e8f0",
    },
    badge: (type) => {
      const colors = {
        "Full-time": { bg: "#dbeafe", color: "#1e40af" },
        "Part-time": { bg: "#fef3c7", color: "#92400e" },
        "Contract": { bg: "#e0e7ff", color: "#3730a3" },
        "Internship": { bg: "#d1fae5", color: "#065f46" },
      };
      const style = colors[type] || colors["Full-time"];

      return {
        display: "inline-block",
        padding: "4px 10px",
        borderRadius: "6px",
        fontSize: "12px",
        fontWeight: "500",
        backgroundColor: style.bg,
        color: style.color,
      };
    },
    actionBtn: {
      border: "none",
      background: "none",
      cursor: "pointer",
      padding: "6px",
      borderRadius: "6px",
      transition: "background 0.2s",
      marginRight: "6px",
    },
    editBtn: {
      color: "#2563eb",
    },
    deleteBtn: {
      color: "#dc2626",
    },
  };

  if (!jobs || jobs.length === 0) {
    return (
      <div style={styles.container}>
        <div style={{ padding: "40px", textAlign: "center", color: "#64748b" }}>
          No jobs found. Click "Add New Job" to create one.
        </div>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <table style={styles.table}>
        <thead>
          <tr>
            <th style={styles.th}>JOB TITLE</th>
            <th style={styles.th}>ROLE</th>
            <th style={styles.th}>LOCATION</th>
            <th style={styles.th}>CTC</th>
            <th style={styles.th}>TYPE</th>
            <th style={styles.th}>POSTED</th>
            <th style={styles.th}>ACTIONS</th>
          </tr>
        </thead>
        <tbody>
          {jobs.map((job) => (
            <tr key={job._id}>
              <td style={styles.td}>
                <div style={{ fontWeight: "600", marginBottom: "4px" }}>
                  {job.title}
                </div>
                <div style={{ fontSize: "12px", color: "#64748b" }}>
                  {job.skillset}
                </div>
              </td>
              <td style={styles.td}>{job.role}</td>
              <td style={styles.td}>{job.location}</td>
              <td style={styles.td}>{job.ctc}</td>
              <td style={styles.td}>
                <span style={styles.badge(job.jobType)}>
                  {job.jobType || "Full-time"}
                </span>
              </td>
              <td style={styles.td}>{formatDate(job.createdAt)}</td>
              <td style={styles.td}>
                <button
                  style={{ ...styles.actionBtn, ...styles.editBtn }}
                  onClick={() => onEdit(job)}
                  title="Edit Job"
                >
                  <Edit size={18} />
                </button>
                <button
                  style={{ ...styles.actionBtn, ...styles.deleteBtn }}
                  onClick={() => onDelete(job._id)}
                  title="Delete Job"
                >
                  <Trash2 size={18} />
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default JobTable;
